const revokeSelfDeviceRefreshTokens = `-- name: RevokeSelfDeviceRefreshTokens :exec
UPDATE iam.refresh_tokens token
SET revoked_at = COALESCE(token.revoked_at, now())
WHERE token.revoked_at IS NULL
  AND EXISTS (
      SELECT 1
      FROM iam.sessions session
      WHERE session.id = token.session_id
        AND session.user_id = $1
        AND session.device_id = $2
  )
`

type RevokeSelfDeviceRefreshTokensParams struct {
	UserID   uuid.UUID  `json:"user_id"`
	DeviceID *uuid.UUID `json:"device_id"`
}

